const STORAGE_KEY = 'todoItems';

const taskInput = document.getElementById('taskInput');
const addBtn = document.getElementById('addBtn');
const taskList = document.getElementById('taskList');
const emptyMsg = document.getElementById('emptyMsg');

function loadTasks() {
  const raw = localStorage.getItem(STORAGE_KEY);
  return raw ? JSON.parse(raw) : [];
}

function saveTasks(tasks) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
}

function renderTasks() {
  const tasks = loadTasks();
  taskList.innerHTML = '';
  emptyMsg.hidden = tasks.length > 0;

  tasks.forEach(function(task, index) {
    const li = document.createElement('li');
    li.textContent = task;

    const deleteBtn = document.createElement('button');
    deleteBtn.textContent = 'Kustuta';
    deleteBtn.className = 'delete';
    deleteBtn.addEventListener('click', function() {
      deleteTask(index);
    });

    li.appendChild(deleteBtn);
    taskList.appendChild(li);
  });
}

function addTask() {
  const text = taskInput.value.trim();
  if (!text) return;

  const tasks = loadTasks();
  tasks.push(text);
  saveTasks(tasks);
  taskInput.value = '';
  renderTasks();
}

function deleteTask(index) {
  const tasks = loadTasks();
  tasks.splice(index, 1);
  saveTasks(tasks);
  renderTasks();
}

addBtn.addEventListener('click', addTask);

taskInput.addEventListener('keydown', function(event) {
  if (event.key === 'Enter') addTask();
});

renderTasks();

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: sans-serif;
  background: #f5f5f5;
  display: flex;
  justify-content: center;
  padding: 40px 16px;
}

.container {
  background: white;
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 4px 20px rgba(0,0,0,0.08);
}

h1 { font-size: 22px; margin-bottom: 16px; }

.add-row { display: flex; gap: 8px; margin-bottom: 16px; }

input[type="text"] {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid #ddd;
  border-radius: 6px;
  font-size: 15px;
}

button {
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
}

#addBtn { background: #4a90e2; color: white; }
#addBtn:hover { background: #357abd; }

ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }

li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: #f9f9f9;
  border-radius: 6px;
  border: 1px solid #eee;
}

.delete { background: #ef5d5d; color: white; padding: 6px 10px; }
.delete:hover { background: #d94444; }

.empty { color: #aaa; font-size: 14px; margin-top: 12px; }
